def generate_square_subsequent_mask(self, sz):


        mask = paddle.zeros([sz, sz], dtype="float32")
        mask_inf = paddle.triu(
            paddle.full(shape=[sz, sz], dtype="float32", fill_value="-inf"), diagonal=1
        )
