def _get_full_filename(root: str | Path, pathname: str | Path) -> Path | None:



        if re.match(r"^/.+", pathname):
            return pathname
        files = list_files(root=root)
        postfix = "/" + str(pathname)
        for i in files:
            if str(i).endswith(postfix):
                return i
        return None

